import math


class RoverController:
    _COMMANDS = {"FORWARD", "BACKWARD", "LEFT", "RIGHT"}

    def __init__(self, move_speed, turn_sensitivity, reverse_turn=False, captured=False):
        self.move_speed = self._positive_number(move_speed, "move_speed")
        self.turn_sensitivity = self._positive_number(turn_sensitivity, "turn_sensitivity")
        self.reverse_turn = bool(reverse_turn)
        self.captured = bool(captured)
        self._x = 0.0
        self._y = 0.0
        self._heading = 0.0

    @staticmethod
    def _positive_number(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(name + " must be a finite positive number")
        value = float(value)
        if not math.isfinite(value) or value <= 0:
            raise ValueError(name + " must be a finite positive number")
        return value

    def update(self, commands, pointer_dx):
        try:
            command_items = tuple(commands)
        except TypeError as exc:
            raise ValueError("commands must be iterable") from exc
        for command in command_items:
            if not isinstance(command, str) or command not in self._COMMANDS:
                raise ValueError("unknown command: " + repr(command))
        command_set = set(command_items)

        if isinstance(pointer_dx, bool) or not isinstance(pointer_dx, (int, float)):
            raise ValueError("pointer_dx must be finite")
        pointer_dx = float(pointer_dx)
        if not math.isfinite(pointer_dx):
            raise ValueError("pointer_dx must be finite")

        if self.captured:
            turn = pointer_dx * self.turn_sensitivity
            if not self.reverse_turn:
                turn = -turn
            self._heading += turn

        forward = int("FORWARD" in command_set) - int("BACKWARD" in command_set)
        strafe = int("LEFT" in command_set) - int("RIGHT" in command_set)
        if forward == 0 and strafe == 0:
            return

        scale = self.move_speed / math.hypot(forward, strafe)
        cosine = math.cos(self._heading)
        sine = math.sin(self._heading)
        self._x += scale * (forward * cosine - strafe * sine)
        self._y += scale * (forward * sine + strafe * cosine)

    def pointer_button(self, button, pressed):
        if button == "PRIMARY" and bool(pressed):
            self.captured = not self.captured

    def key_event(self, key, pressed):
        if key == "ESCAPE" and bool(pressed):
            self.captured = False

    def get_position(self):
        return (self._x, self._y)

    def get_direction(self):
        return (math.cos(self._heading), math.sin(self._heading))

    def get_transform(self):
        cosine = math.cos(self._heading)
        sine = math.sin(self._heading)
        return [[cosine, -sine, self._x], [sine, cosine, self._y], [0.0, 0.0, 1.0]]

